INSERT INTO `argomenticompetenze` (`IDArgomentiCompetenza`, `argomento`, `note`, `idTitoloCompetenza`, `idTutorAziendale`) VALUES
(17, 'Si occupa di mantenere la postazione di lavoro pulita e ordinata.', '', 8, NULL),
(18, 'Utilizza adeguatamente i supporti informatici specifici per le mansioni da svolgere.', 'Utilizza adeguatamente i supporti informatici specifici per le mansioni da svolgere.', 8, NULL),
(19, 'Recupera autonomamente le informazioni necessarie usando Internet, manuali o l\'AI?', 'Recupera autonomamente le informazioni necessarie usando Internet, manuali o l\'AI?', 8, NULL),
(20, 'È in grado di svolgere le mansioni assegnate in modo autonomo?', 'È in grado di svolgere le mansioni assegnate in modo autonomo?', 8, NULL),
(24, 'Ha appreso in modo significativo quanto gli è stato insegnato durante il percorso formativo?', 'Si', 8, NULL),
(27, 'Analizza e decodifica le mansioni che gli vengono assegnate pianificandole in modo autonomo', 'Competenza professionalizzante. Livello: 10 - 8 - 6 - 4 - 2 - 0', 10, NULL),
(28, 'È in grado di svolgere il compito che viene assegnato utilizzando in modo adeguato la strumentazione?', 'Competenza professionalizzante. Livello: 10 - 8 - 6 - 4 - 2 - 0', 10, NULL),
(29, 'È in grado di recuperare autonomamente le informazioni necessarie allo svolgimento delle mansioni assegnate utilizzando internet e/o manuali.', 'Competenza professionalizzante. Livello: 10 - 8 - 6 - 4 - 2 - 0', 10, NULL),
(30, 'È in grado di proporre soluzioni alternative al consueto processo di lavoro', 'Competenza professionalizzante. Livello: 10 - 8 - 6 - 4 - 2 - 0', 10, NULL),
(32, 'Ha appreso in modo significativo tutto ciò che gli è stato insegnato e/o appreso durante l’intero percorso di alternanza?', 'Competenza professionalizzante. Livello: 10 - 8 - 6 - 4 - 2 - 0', 10, NULL),
(33, ' Osserva la normativa vigente in materia di sicurezza nello svolgimento dell’attività assegnata e nella cura degli strumenti affidati', 'Comportamenti: Valutazione 10  8  6  4  2  0\r\n\r\n', 10, NULL),
(37, 'E’ disponibile a lavorare con i colleghi e rispetta le regole generali dell’ambiente di lavoro', 'Comportamenti. Valutazione: 10 - 8 - 6 - 4 - 2 - 0', 10, NULL),
(38, 'Agisce in modo responsabile e interessato cogliendo le opportunità del percorso', 'Competenze chiave di CIttadinanza. Valutazione: 10 - 8 - 6 - 4 - 2 - 0', 10, NULL),
(39, 'Sa documentarsi e svolgere ricerche in modo autonomo riesaminando il lavoro svolto per migliorare le proprie competenze ', 'Competenze chiave di CIttadinanza. Valutazione: 10 - 8 - 6 - 4 - 2 - 0', 10, NULL),
(40, 'Dimostra un atteggiamento costruttivo chiedendo spiegazioni e utilizzando modalità comunicative adeguate anche in lingua straniera', 'Competenze chiave di CIttadinanza. Valutazione: 10 - 8 - 6 - 4 - 2 - 0', 10, NULL);
